import type { ChainId } from './chains';

export type Role = 'flatmate' | 'tutor';

/** Each character's avatar art is assets/avatars/{id}.svg, generated by scripts/avatars.mjs. */
export interface Character {
  id: string;
  name: string;
  /** Shown after the name, like a team in a work chat. */
  team: string;
  role: Role;
  chapter: string;
}

